  1	package hotel.reservations;
  2	
  3	import hotel.documents.ReservationReceipt;
  4	import hotel.messages.EmailSender;
  5	import hotel.rooms.Room;
  6	import hotel.rooms.Rooms;
  7	import java.math.BigDecimal;
  8	
  9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 10	public final class ReservationService {
 11	
 12	    static final String HOTEL_NAME = "Pousada Maré Alta";
 13	
 14	    private final Rooms rooms;
 15	    private final ReservationStore store;
 16	    private final PriceCalculator priceCalculator;
 17	    private final EmailSender emailSender;
 18	
 19	    public ReservationService(
 20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 21	        this.rooms = rooms;
 22	        this.store = store;
 23	        this.priceCalculator = priceCalculator;
 24	        this.emailSender = emailSender;
 25	    }
 26	
 27	    public synchronized Reservation create(NewReservation request) {
 28	        if (!request.checkOut().isAfter(request.checkIn())) {
 29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 30	        }
 31	        if (request.guests() < 1) {
 32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 33	        }
 34	        Room room = rooms.find(request.roomNumber())
 35	                .orElseThrow(() -> new HotelException(
 36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 37	        if (request.guests() > room.capacity()) {
 38	            throw new HotelException(
 39	                    ErrorCode.CAPACITY_EXCEEDED,
 40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 41	        }
 42	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 43	            throw new HotelException(
 44	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 45	        }
 46	
 47	        Price price = switch (request.ratePlan()) {
 48	            case CORPORATE -> {
 49	                if (request.companyCode() == null || !isValidCompanyCode(request.companyCode())) {
 50	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "invalid or missing company code");
 51	                }
 52	                yield priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
 53	            }
 54	            case WEEKEND_PACKAGE -> {
 55	                if (!PriceCalculator.isWeekendPackageValid(request.checkIn(), request.checkOut())) {
 56	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package must be Friday to Sunday");
 57	                }
 58	                yield priceCalculator.calculateWeekendPackage(room, request.checkIn(), request.checkOut());
 59	            }
 60	            case LONG_STAY -> {
 61	                int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
 62	                if (nights < 7) {
 63	                    throw new HotelException(ErrorCode.INVALID_REQUEST, "long stay requires at least 7 nights");
 64	                }
 65	                yield priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), null);
 66	            }
 67	            case STANDARD, NON_REFUNDABLE -> priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), null);
 68	        };
 69	        return store.add(request, price);
 70	    }
 71	
 72	    private static boolean isValidCompanyCode(String code) {
 73	        return code.equals("TECNOSUL") || code.equals("AGROVALE") || code.equals("FARMAVIDA");
 74	    }
 75	
 76	    public Reservation find(long reservationId) {
 77	        return store.find(reservationId)
 78	                .orElseThrow(() -> new HotelException(
 79	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 80	    }
 81	
 82	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 83	    public synchronized Reservation confirm(long reservationId) {
 84	        Reservation reservation = find(reservationId);
 85	        if (reservation.status() != ReservationStatus.PENDING) {
 86	            throw notAllowed(reservation, "confirm");
 87	        }
 88	        reservation.confirmPayment();
 89	        store.update(reservation);
 90	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
 91	        emailSender.send(
 92	                reservation.guest().email(),
 93	                "Reserva confirmada - " + HOTEL_NAME,
 94	                confirmationEmailBody(reservation, receipt));
 95	        return reservation;
 96	    }
 97	
 98	    /**
 99	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
100	     * reservation was never paid, so nothing comes back).
101	     */
102	    public synchronized Reservation cancel(long reservationId) {
103	        Reservation reservation = find(reservationId);
104	        if (reservation.status() != ReservationStatus.PENDING
105	                && reservation.status() != ReservationStatus.CONFIRMED) {
106	            throw notAllowed(reservation, "cancel");
107	        }
108	        BigDecimal refund = switch (reservation.ratePlan()) {
109	            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
110	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
111	            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().divide(new java.math.BigDecimal("2"), 2, java.math.RoundingMode.HALF_EVEN));
112	        };
113	        reservation.cancel(refund);
114	        store.update(reservation);
115	        return reservation;
116	    }
117	
118	    public synchronized Reservation checkIn(long reservationId) {
119	        Reservation reservation = find(reservationId);
120	        if (reservation.status() != ReservationStatus.CONFIRMED) {
121	            throw notAllowed(reservation, "check in");
122	        }
123	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
124	        store.update(reservation);
125	        return reservation;
126	    }
127	
128	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
129	    public synchronized ReservationReceipt checkOut(long reservationId) {
130	        Reservation reservation = find(reservationId);
131	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
132	            throw notAllowed(reservation, "check out");
133	        }
134	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
135	        store.update(reservation);
136	        return new ReservationReceipt(reservation, roomOf(reservation));
137	    }
138	
139	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
140	    public ReservationReceipt receiptCopy(long reservationId) {
141	        Reservation reservation = find(reservationId);
142	        if (!reservation.isPaid()) {
143	            throw notAllowed(reservation, "issue a receipt for");
144	        }
145	        return new ReservationReceipt(reservation, roomOf(reservation));
146	    }
147	
148	    private Room roomOf(Reservation reservation) {
149	        return rooms.find(reservation.roomNumber()).orElseThrow();
150	    }
151	
152	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
153	        return "Olá, " + reservation.guest().name() + "!\n\n"
154	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
155	                + receipt.text() + "\n"
156	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
157	                + "Até breve!\n";
158	    }
159	
160	    private static HotelException notAllowed(Reservation reservation, String operation) {
161	        return new HotelException(
162	                ErrorCode.OPERATION_NOT_ALLOWED,
163	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
164	    }
165	}
166	package hotel.reservations;
167	
168	import hotel.rooms.Room;
169	import hotel.rooms.RoomType;
170	import java.math.BigDecimal;
171	import java.math.RoundingMode;
172	import java.time.DayOfWeek;
173	import java.time.LocalDate;
174	import java.time.Month;
175	
176	/**
177	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
178	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
179	 * (half-even) at every step.
180	 */
181	public final class PriceCalculator {
182	
183	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
184	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
185	    static final BigDecimal CORPORATE_TECNOSUL_DISCOUNT = new BigDecimal("0.12");
186	    static final BigDecimal CORPORATE_AGROVALE_DISCOUNT = new BigDecimal("0.18");
187	    static final BigDecimal CORPORATE_FARMAVIDA_DISCOUNT = new BigDecimal("0.25");
188	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
189	
190	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
191	        int nights = 0;
192	        BigDecimal subtotal = cents(BigDecimal.ZERO);
193	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
194	            subtotal = subtotal.add(nightPrice(room, night));
195	            nights++;
196	        }
197	        BigDecimal discount = switch (ratePlan) {
198	            case STANDARD -> cents(BigDecimal.ZERO);
199	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
200	            case CORPORATE -> cents(subtotal.multiply(getCorporateDiscount(companyCode)));
201	            case LONG_STAY -> cents(subtotal.multiply(LONG_STAY_DISCOUNT));
202	            case WEEKEND_PACKAGE -> cents(BigDecimal.ZERO);
203	        };
204	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
205	    }
206	
207	    public Price calculateWeekendPackage(Room room, LocalDate checkIn, LocalDate checkOut) {
208	        BigDecimal packagePrice = switch (room.type()) {
209	            case STANDARD -> new BigDecimal("520.00");
210	            case DELUXE -> new BigDecimal("820.00");
211	            case SUITE -> new BigDecimal("1200.00");
212	        };
213	        return new Price(2, packagePrice, cents(BigDecimal.ZERO), packagePrice);
214	    }
215	
216	    private static BigDecimal getCorporateDiscount(String companyCode) {
217	        return switch (companyCode) {
218	            case "TECNOSUL" -> CORPORATE_TECNOSUL_DISCOUNT;
219	            case "AGROVALE" -> CORPORATE_AGROVALE_DISCOUNT;
220	            case "FARMAVIDA" -> CORPORATE_FARMAVIDA_DISCOUNT;
221	            default -> throw new IllegalArgumentException("Invalid company code: " + companyCode);
222	        };
223	    }
224	
225	    BigDecimal nightPrice(Room room, LocalDate night) {
226	        BigDecimal nightlyRate = room.nightlyRate();
227	        if (isHighSeason(night)) {
228	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
229	        }
230	        return cents(nightlyRate);
231	    }
232	
233	    /** High season: from December 15 to the end of February, and the whole of July. */
234	    static boolean isHighSeason(LocalDate date) {
235	        Month month = date.getMonth();
236	        return month == Month.JANUARY
237	                || month == Month.FEBRUARY
238	                || month == Month.JULY
239	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
240	    }
241	
242	    static BigDecimal cents(BigDecimal value) {
243	        return value.setScale(2, RoundingMode.HALF_EVEN);
244	    }
245	
246	    static boolean isWeekendPackageValid(LocalDate checkIn, LocalDate checkOut) {
247	        if (!checkOut.minusDays(1).equals(checkIn.plusDays(1))) {
248	            return false;
249	        }
250	        return checkIn.getDayOfWeek() == DayOfWeek.FRIDAY && checkOut.getDayOfWeek() == DayOfWeek.SUNDAY;
251	    }
252	}
253	package hotel.reservations;
254	
255	public enum RatePlan {
256	    /** Full price; the guest gets everything back when cancelling a confirmed reservation. */
257	    STANDARD,
258	    /** 15% off, but nothing comes back on cancellation. */
259	    NON_REFUNDABLE,
260	    /** Corporate plan with company discounts. */
261	    CORPORATE,
262	    /** Weekend package: fixed price for 2 nights (Friday to Sunday). */
263	    WEEKEND_PACKAGE,
264	    /** Long stay discount: 10% off for 7 nights or more. */
265	    LONG_STAY
266	}
267	package hotel.reservations;
268	
269	import java.time.LocalDate;
270	
271	public record NewReservation(
272	        int roomNumber, Guest guest, LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
273	        String companyCode) {
274	}
275	package hotel;
276	
277	import hotel.messages.EmailSender;
278	import hotel.messages.SentMessages;
279	import hotel.reports.OccupancyReport;
280	import hotel.reports.RevenueReport;
281	import hotel.reservations.PriceCalculator;
282	import hotel.reservations.ReservationService;
283	import hotel.reservations.ReservationStore;
284	import hotel.rooms.Rooms;
285	import hotel.web.HttpApi;
286	import io.javalin.Javalin;
287	import javax.sql.DataSource;
288	
289	/** Puts the inn's pieces together and runs the HTTP server. */
290	public final class Hotel {
291	
292	    private final Javalin server;
293	
294	    public Hotel(DataSource dataSource) {
295	        Rooms rooms = new Rooms(dataSource);
296	        ReservationStore store = new ReservationStore(dataSource);
297	        SentMessages sentMessages = new SentMessages(dataSource);
298	        ReservationService reservations =
299	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
300	        HttpApi api = new HttpApi(
301	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
302	        this.server = api.server();
303	    }
304	
305	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
306	    public int start(int port) {
307	        server.start(port);
308	        return server.port();
309	    }
310	
311	    public void stop() {
312	        server.stop();
313	    }
314	
315	    public static void main(String[] args) {
316	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
317	        Database database = new Database(System.getenv());
318	        new Hotel(database.dataSource()).start(port);
319	    }
320	}

