152	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
153	        return "Olá, " + reservation.guest().name() + "!\n\n"
154	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
155	                + receipt.text() + "\n"
156	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
157	                + "Até breve!\n";
