166	package hotel.reservations;
167	
168	import hotel.rooms.Room;
169	import hotel.rooms.RoomType;
170	import java.math.BigDecimal;
171	import java.math.RoundingMode;
172	import java.time.DayOfWeek;
173	import java.time.LocalDate;
174	import java.time.Month;
175	
176	/**
177	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
178	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
179	 * (half-even) at every step.
180	 */
181	public final class PriceCalculator {
182	
183	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
184	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
185	    static final BigDecimal CORPORATE_TECNOSUL_DISCOUNT = new BigDecimal("0.12");
186	    static final BigDecimal CORPORATE_AGROVALE_DISCOUNT = new BigDecimal("0.18");
187	    static final BigDecimal CORPORATE_FARMAVIDA_DISCOUNT = new BigDecimal("0.25");
188	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
189	
190	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
191	        int nights = 0;
192	        BigDecimal subtotal = cents(BigDecimal.ZERO);
193	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
194	            subtotal = subtotal.add(nightPrice(room, night));
195	            nights++;
196	        }
197	        BigDecimal discount = switch (ratePlan) {
198	            case STANDARD -> cents(BigDecimal.ZERO);
199	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
200	            case CORPORATE -> cents(subtotal.multiply(getCorporateDiscount(companyCode)));
201	            case LONG_STAY -> cents(subtotal.multiply(LONG_STAY_DISCOUNT));
202	            case WEEKEND_PACKAGE -> cents(BigDecimal.ZERO);
203	        };
204	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
205	    }
206	
207	    public Price calculateWeekendPackage(Room room, LocalDate checkIn, LocalDate checkOut) {
208	        BigDecimal packagePrice = switch (room.type()) {
209	            case STANDARD -> new BigDecimal("520.00");
210	            case DELUXE -> new BigDecimal("820.00");
211	            case SUITE -> new BigDecimal("1200.00");
212	        };
213	        return new Price(2, packagePrice, cents(BigDecimal.ZERO), packagePrice);
214	    }
215	
216	    private static BigDecimal getCorporateDiscount(String companyCode) {
217	        return switch (companyCode) {
218	            case "TECNOSUL" -> CORPORATE_TECNOSUL_DISCOUNT;
219	            case "AGROVALE" -> CORPORATE_AGROVALE_DISCOUNT;
220	            case "FARMAVIDA" -> CORPORATE_FARMAVIDA_DISCOUNT;
221	            default -> throw new IllegalArgumentException("Invalid company code: " + companyCode);
222	        };
223	    }
224	
225	    BigDecimal nightPrice(Room room, LocalDate night) {
226	        BigDecimal nightlyRate = room.nightlyRate();
227	        if (isHighSeason(night)) {
228	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
229	        }
230	        return cents(nightlyRate);
231	    }
232	
233	    /** High season: from December 15 to the end of February, and the whole of July. */
234	    static boolean isHighSeason(LocalDate date) {
235	        Month month = date.getMonth();
236	        return month == Month.JANUARY
237	                || month == Month.FEBRUARY
238	                || month == Month.JULY
239	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
240	    }
241	
242	    static BigDecimal cents(BigDecimal value) {
243	        return value.setScale(2, RoundingMode.HALF_EVEN);
244	    }
245	
246	    static boolean isWeekendPackageValid(LocalDate checkIn, LocalDate checkOut) {
247	        if (!checkOut.minusDays(1).equals(checkIn.plusDays(1))) {
248	            return false;
249	        }
250	        return checkIn.getDayOfWeek() == DayOfWeek.FRIDAY && checkOut.getDayOfWeek() == DayOfWeek.SUNDAY;
251	    }
252	}
